-- A FUNCTIONAL unique index, not a plain column unique. The index is the guard, not a prior read — two simultaneous identical creates must produce one row and one 422. The reason reaches the customer here and not only the admin: the category is the primary non-colour carrier of price band on the seat map, so `Premium` and `premium` coexisting would draw two legend rows on every seat map for what a customer reads as one category (P-ADM-23).
CREATE UNIQUE INDEX uq_seat_category__name_ci ON seat_category ((lower(trim(name))));

-- --------------------------------------------------------------------------
-- users - One row per person who holds an account — customer, manager or admin; the identity every booking, audit row and reset token points at.
-- P-ACC-01 (E5 S4, 'The complete field list of the user row') · E8 S7.5 · FR-ADR-050
CREATE TABLE users (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- P-ACC-09 — 'booking.user_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT'; EP-ADM-22/EP-ADM-23 return user_id as 'integer'; P-XCT-03's worked example uses actor_user_id 17 - INTEGER, not uuid. Three documents spell the referencing column `integer`, so the brief's uuid default does not apply here. NO DOCUMENT STATES THE GENERATION MECHANISM (identity column vs sequence) — audit_log is the only table where a document says 'identity'.
    email                      text NOT NULL,  -- P-ACC-01 step 5 and its validation table · E8 S7.5 · P-XCT-06 preconditions - Stored AS ENTERED, 3..254 characters after trimming. Uniqueness is a unique index on `lower(email)` — E8 S7.5 explicitly refuses a second lowercased column ('two fields to keep in step'), so this is NOT citext and NOT a stored lowercase column. Written once by P-ACC-01 and never updated by anything (S-ACC-06 asserts the mapper's changed-attribute set never contains `email`).
    password_hash              text NOT NULL,  -- P-ACC-01 (field table: `text`, NOT NULL) · P-ACC-03 (bcrypt, BCRYPT_COST default 12) · S-ACC-02 - bcrypt. The ALGORITHM IS NAMED BY THE DOCUMENTS (P-ACC-03: 'Algorithm bcrypt'; E8 S7.5; FR-ADR-050) — nothing is inferred. NOT NULL on every row without exception: a manager account with no usable password carries a real bcrypt digest of 32 discarded CSPRNG bytes, drawn PER ROW so two such rows never share a value (S-ACC-02 asserts count(*) - count(DISTINCT password_hash) = 0 over rows with last_signed_in_at IS NULL). A nullable column is refused by name, because a null test before the verification is the early return P-ACC-03's timing property forbids.
    role                       text NOT NULL,  -- S3.1 'The four roles' (Modelled as: `user.role = 'customer'` / `'manager'` / `'admin'`) · P-XCT-05 preconditions ('exactly one role value in a single column') · FR-ADR-009 · SRC-003 C-1 - PROVISIONAL that the manager value exists at all (SRC-003 C-1). Roles are mutually exclusive, one column, never a many-to-many table (S3.1, FR-ADR-050). Set to 'customer' by the application at registration and to 'manager' by P-ADM-17; NO ENDPOINT EVER CREATES 'admin' (S-ADM-18 asserts every /api/admin POST and PUT leaves the admin count unchanged and that `role = 'admin'` appears only in scripts/seed.py). NO DOCUMENT STATES THE DATABASE REPRESENTATION — see gaps. closed vocabulary, enforced by a CHECK rather than a PostgreSQL enum type
    password_version           integer NOT NULL,  -- P-ACC-05 ('an integer starting at 1 and incremented on every password change') · P-ACC-01 step 5 · P-ACC-08 step 4 - THE SESSION-INVALIDATION COUNTER. It is the JWT's `pv` claim; the authorisation dependency loads the user row by primary key on every authenticated request and rejects the token when `pv` does not match this column (P-ACC-05 exception 4). Written as 1 by the application at insert — no document states a database default. Incremented by P-ACC-08 only: `password_version = password_version + 1`.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- P-ACC-01 step 5 · FR-ADR-018 ('`created_at` and `updated_at` are `timestamptz` and default to `now()` at the database') · EP-ADM-22 returns it - Required on every table in the schema — S-XCT-09 asserts that no table in `public` other than `alembic_version` lacks a `created_at`.
    last_signed_in_at          timestamptz,  -- P-ACC-01 (field table: timestamptz, UTC, nullable) · P-ACC-02 step 4 · P-ACC-08 step 4 - NULL means the account has never signed in — a real and expected state, not a defect. Written from the INJECTED CLOCK on every successful sign-in (`UPDATE users SET last_signed_in_at = :now WHERE id = :id`) and inside P-ACC-08's reset transaction. NOT written on a failed attempt. `has_signed_in` on EP-ADM-22 is DERIVED as `last_signed_in_at IS NOT NULL` and is never stored (S-ADM-18 asserts no `has_signed_in` column exists in information_schema).
    PRIMARY KEY (id),
    CONSTRAINT ck_users__role CHECK (role IN ('customer', 'manager', 'admin'))
);
-- Email is the identity, unique case-insensitively. It is an EXPRESSION index, not a column constraint — a second lowercased column is refused by name in S7.5. It is the guard, not a prior read: P-ACC-01 step 6 catches the unique violation and translates it to 409 EMAIL_ALREADY_REGISTERED, and S-ACC-01 asserts 20 simultaneous identical registrations produce exactly 1 success and 19 conflicts with no 500.
CREATE UNIQUE INDEX uq_users__email_ci ON users ((lower(email)));

-- --------------------------------------------------------------------------
-- admin_grant - One row per email address an existing admin has granted admin access to. A sign-up or sign-in with that address (trimmed, case-insensitive) makes the account admin; deleting the row makes an admin account with that address a customer again.
-- SRC-008 ROLE-1 and its ADDENDUM · S-ADM-30 · P-ADM-18 · P-ADM-19
CREATE TABLE admin_grant (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- FR-ADR-017 (bigint identity on every table) · S-ADM-30 (removing one deletes that grant row) - The audit row of a removal records the id the deleted row held, as manager.screen_unassigned does.
    email                      text NOT NULL,  -- SRC-008 ROLE-1 ('typing their email into a section in setting') · S-ADM-30 (stored and compared trimmed and case-insensitively) - Stored trimmed and lower-cased by the application, so the unique index on lower(email) and the comparison with users.email agree.
    granted_by                 bigint NOT NULL,  -- SRC-008 ROLE-1 ('only an existing admin can make someone an admin') · S-ADM-02 (who made the change) - The admin who typed the address. The audit row carries the same id as actor_user_id.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- S-XCT-09 · no table in `public` other than `alembic_version` may lack a `created_at` · FR-ADR-018 - Row metadata; the list orders by email, not by this.
    PRIMARY KEY (id),
    CONSTRAINT fk_admin_grant__granted_by FOREIGN KEY (granted_by) REFERENCES users (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- One grant per address, case-insensitively. The guard, not the read before it: a simultaneous twin add is a unique violation translated to 422.
CREATE UNIQUE INDEX uq_admin_grant__email_ci ON admin_grant ((lower(email)));

-- --------------------------------------------------------------------------
-- audit_log - One append-only row per privileged write, inserted in the same database transaction as the change itself, recording who, when, which action, which row, and the changed fields before and after.
-- P-XCT-03 · E8 S7.3 · P-ADM-19 · FR-ADR-019
CREATE TABLE audit_log (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- E8 S7.3 and P-ADM-19 and FR-ADR-019 all spell it '`bigint` identity' · P-RPT-11 step 3 (cursor on `id`, ordered descending) - THE ONLY PRIMARY KEY IN THIS CLUSTER A DOCUMENT GIVES A GENERATION MECHANISM FOR. EP-RPT-04's `cursor` is a positive integer audit row id and is a BOUND, not a lookup: a well-formed id naming no row returns 200, never 404.
    occurred_at                timestamptz NOT NULL,  -- E8 S7.3 · P-ADM-19 · S-XCT-06 (`SELECT data_type ... column_name='occurred_at'` returns 'timestamp with time zone') - UTC. S-XCT-06 additionally asserts the value the APPLICATION BINDS is an aware datetime whose utcoffset() is zero — so it is written by the application from the injected clock, not by a database default.
    actor_user_id              bigint NOT NULL,  -- E8 S7.3 · P-ADM-19 · P-XCT-03 server-side validation · S-XCT-06 (`is_nullable` returns NO, and one foreign key row in pg_constraint) - NEVER A ROLE NAME AND NEVER A SERVICE ACCOUNT — both substitutes are forbidden in terms. The seed script is the ONLY exemption from the same-transaction audit rule anywhere in the product, precisely because at its earliest writes no user row exists to point at (P-XCT-30); it writes zero audit rows and no application code path inherits that exemption.
    actor_role                 text NOT NULL,  -- E8 S7.3 · P-ADM-19 · S-XCT-06 (asserted still to read 'admin' after user 17's role is changed to manager) - THE ROLE THE ACTOR HELD AT THE TIME, COPIED RATHER THAN JOINED. Never resolved by a join at read time. NO DOCUMENT STATES THE COLUMN TYPE — `text` is reported rather than `enum:user_role` because the point of the column is that it is a frozen copy, and a shared enum type ties historical rows to a live vocabulary. See gaps; this is the merge owner's call.
    action                     text NOT NULL,  -- E8 S7.3 · P-ADM-19's controlled vocabulary table (the single source of the strings for the whole product) · FR-ADR-019 - A CLOSED controlled vocabulary, enumerated by P-ADM-19 and by no one else. ENFORCED IN THE APPLICATION, NOT IN THE DATABASE: S-ADM-02 requires a closed Python enum `AuditAction`, S-XCT-07 requires a module-level tuple `AUDIT_ACTIONS` in backend/app/domain/audit.py, and a non-member is refused at a boundary check BEFORE THE TRANSACTION OPENS (asserted by a statement listener recording zero statements). No document asks for a database CHECK or a Postgres enum, so none is proposed. The string already got wrong once: a base-price change is `showtime.base_price_changed`; `showtime.price_changed` is NOT a member and never has been, although FR-ADR-019's own example text still shows it.
    entity_type                text NOT NULL,  -- E8 S7.3 · P-ADM-19 - The table the change landed on. Values seen in the vocabulary table: movie, showtime, seat_category, cinema, screen, seat, user, manager_screen_assignment, language, certification, genre, format.
    entity_id                  bigint NOT NULL,  -- E8 S7.3 · P-ADM-19 - The primary key of the changed row. NO FOREIGN KEY MAY EXIST ON THIS COLUMN — S-ADM-18 asserts the FK count on audit_log.entity_id is 0, because for `manager.screen_unassigned` it deliberately names a row that no longer exists and 'a column that resolves by lying about what it points at is worse than one that honestly points at something gone'. Nothing may join it to a live table for that action. Width is not stated by any document — see gaps.
    before                     jsonb,  -- E8 S7.3 · P-ADM-19 · P-XCT-03 server-side validation - ONLY THE FIELDS THAT CHANGED, never a whole-row snapshot (S-XCT-06 asserts jsonb_object_keys(before) counts 1 for a single-field change). NULL FOR A CREATION. Carries no credential (`password_hash`, `password_version` excluded from every entity_type='user' row), no card-shaped key, and no poster bytes — only the S3 object key.
    after                      jsonb,  -- E8 S7.3 · P-ADM-19 - Null for a withdrawal that changes nothing else — including `manager.screen_unassigned`, whose `before` carries exactly `{"user_id": n, "screen_id": n}`. Same credential and card-data exclusions as `before`. Returned VERBATIM by EP-RPT-04 and never unit-converted.
    request_id                 text NOT NULL,  -- E8 S7.3 · P-ADM-19 · P-XCT-03 happy path step 4 and preconditions · FR-ADR-056 - The request id from the log context, so an audit row joins to the log lines. Matches ^[0-9a-f]{8}$ (S-XCT-06). NO DOCUMENT STATES ITS NULLABILITY EXPLICITLY — reported NOT NULL because P-XCT-03's precondition requires it to be available before the transaction opens and every audit row is written from a request; flag it if the merge disagrees.
    PRIMARY KEY (id),
    CONSTRAINT fk_audit_log__actor_user_id FOREIGN KEY (actor_user_id) REFERENCES users (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- Every read of this table is bounded by the date window, deliberately, because audit_log is the largest table in the system and never shrinks. DERIVED FROM THE NAMED QUERY — no document declares an index on this table.
CREATE INDEX ix_audit_log__occurred_at ON audit_log (occurred_at);

-- --------------------------------------------------------------------------
-- movie - One film, typed in by hand by an admin; carries the six details a customer chooses on, the poster key, and the two independent visibility gates (publication and the display window).
-- P-ADM-01 (docs/03 PRD/sections/E6_admin.md S4) + FR-ADR-021 + SRC-001 §5.1.1
CREATE TABLE movie (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- FR-ADR-017 - NOT uuid. FR-ADR-017 rules bigint identity on EVERY table, database-generated, explicitly rejecting UUIDv4/v7/ULID; the oversell index (showtime_id, seat_id) is named as the deciding reason. Every criterion addresses movies by small integers (GET /api/movies/11; poster key regex ^posters/\d+/[0-9a-f]{32}$; GET /api/movies/abc returns 422). This contradicts the BRIEF's uuid default and the 'application generates ids' default — reporting the source as instructed.
    title                      text NOT NULL,  -- P-ADM-01 server-side validation table; EP-ADM-02 - 1..200 characters after trimming, enforced at the API (422). DELIBERATELY NOT UNIQUE — FR-ADR-021: 'No natural key. No unique constraint on title.' A re-release is a legitimate second row.
    synopsis                   text NOT NULL,  -- P-ADM-01 server-side validation table; EP-ADM-02 body - EP-ADM-02 declares it 'string, 0..4000, required' — required on the wire, so NOT NULL, but an empty string is a legal value. Plain text, no markup (P-BRW-02).
    runtime_minutes            integer NOT NULL,  -- P-ADM-01; SRC-001 §5.1.1 - >= 1, whole minutes. Read by the showtime form to PREFILL ends_at, never to derive it — S-ADM-09 asserts changing runtime_minutes leaves every stored showtime.ends_at byte-identical.
    certification_id           bigint NOT NULL,  -- P-ADM-01; FR-ADR-021 - FK to the certification lookup table. FR-ADR-021: a lookup table, not free text and not a PostgreSQL enum. P-BRW-02: the wire shape is {id, name} and THERE IS NO code COLUMN — 'No code column is added.'
    language_id                bigint NOT NULL,  -- P-ADM-01; FR-ADR-021; SRC-001 §5.1.3 - FK to the language lookup table. It is a customer-facing filter facet (P-BRW-04), applied to the movie row and not to a showtime.
    poster_object_key          text,  -- P-ADM-03; FR-ADR-021; FR-ADR-061 - The S3 OBJECT KEY, never a URL — 'moving buckets does not rewrite every row' (FR-ADR-021). Nullable because a film is drafted before its poster is uploaded; a film cannot be PUBLISHED with a null key, and that is a publish-time check inside the transaction, explicitly NOT a column constraint (P-ADM-05, FR-ADR-021). Key shape asserted by S-ADM-25: ^posters/\d+/[0-9a-f]{32}$, carrying no part of the client's filename. NAME COLLISION — see notes: two Bible stories call this column poster_key.
    published_at               timestamptz,  -- P-BRW-01; P-ADM-05; FR-ADR-021 - Gate 1 of 2. Null means draft. Server-stamped from the injected clock at publish, never typed by an admin, so it keeps its zone and is serialised as a real instant (EP-ADM-03). The read path tests ONLY 'IS NOT NULL' and NEVER compares it to the clock — a future-dated published_at would duplicate display_from. Unpublish sets it back to null (P-ADM-06). Also the default listing sort key: ORDER BY published_at DESC (P-BRW-03, FR-ADR-021).
    display_from               timestamptz,  -- P-ADM-04; P-BRW-01; FR-ADR-021 - INCLUSIVE lower bound of gate 2. Stored as a UTC instant converted from the naive local Asia/Kolkata value the admin typed; the server 'adds no day, rounds nothing to midnight and derives neither end from the other'. NULLABLE and a null FAILS the window predicate — 'there is no three-valued subtlety'; the query carries no COALESCE (asserted by S-BRW-01).
    display_until              timestamptz,  -- P-ADM-04; P-BRW-01; FR-ADR-021 - EXCLUSIVE upper bound. The ADMIN types the exclusive end instant; the server shifts nothing. Nullable, and null fails the predicate. Must be strictly greater than display_from IN THE MERGED ROW (a PATCH sending one half alone is checked against the stored other half). Also carried on the customer listing payload, because the date strip is built from max(display_until) (P-BRW-02, P-BRW-04).
    version                    integer NOT NULL,  -- P-ADM-02; FR-ADR-035; S-ADM-14 - Optimistic concurrency. Set to 1 by the application on insert; incremented by exactly 1 on every successful mutating write. S-ADM-14 asserts the EXACT set of tables carrying a column named version: movie, showtime, screen, seat_category, cinema — and no others. A no-op write does not increment it. Default is application-set, not database-side, per P-ADM-01 step 4 ('inserts the movie row with ... version = 1').
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- EP-ADM-01 (docs/03 PRD/api/contract.json); S-ADM-23 - Required by the admin film list: 'ORDER BY created_at DESC, id DESC - a total order, because created_at alone is not one: two films created in the same transaction share an instant ... The seed script creates its films in one transaction, so the tie is not hypothetical.' DEFAULT now() at the database (FR-ADR-018: 'created_at and updated_at ... default to now() at the database'; the injected clock governs domain decisions, the database clock governs row metadata).
    PRIMARY KEY (id),
    CONSTRAINT fk_movie__certification_id FOREIGN KEY (certification_id) REFERENCES certification (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_movie__language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

-- --------------------------------------------------------------------------
-- password_reset_token - One row per password-reset request: the SHA-256 of a token that is never stored, its expiry, whether it was spent, and the two separate columns that track the worker's send of the reset email.
-- P-ACC-07 step 5 and its two-column table · P-ACC-08 step 4 · E4 P-TKT-12
CREATE TABLE password_reset_token (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- P-TKT-12 server-side validation — '`reset_token_id`: integer, positive, existing' · S-TKT-15 (`WHERE id=:t`) - The queue message carries this id and NEVER the token. No document states the generation mechanism.
    user_id                    bigint NOT NULL,  -- P-ACC-07 step 5 ('a `password_reset_token` row holding `user_id` ...') · S-ACC-07 (`WHERE user_id=:id`) - The account the link is for. P-TKT-12 validates that the message's `user_id` matches this column; a mismatch is dead-lettered, never sent.
    token_sha256               text NOT NULL,  -- P-ACC-07 step 5 ('`token_sha256` (the SHA-256 of the token, hex)') · S-ACC-07 - SHA-256 hex of a 43-character URL-safe token drawn from 32 CSPRNG bytes. ONLY THE HASH IS STORED — 'somebody who can read the table cannot mint a session from it'. P-ACC-08 step 1 looks the row up by this value. S-ACC-07 asserts the 43 characters appear in `SELECT password_reset_token::text`, in the 202 body and in DEBUG-level stdout NOWHERE. DO NOT ADD A PLAINTEXT TOKEN COLUMN: OPEN-RESETTOKEN-01 is RULED by SRC-004 R-3 - the database keeps only token_sha256; the plaintext rides in the queue message only.
    expires_at                 timestamptz NOT NULL,  -- P-ACC-07 step 5 and its worked example ('`expires_at = created_at + PASSWORD_RESET_TTL_SECONDS`') - PASSWORD_RESET_TTL_SECONDS default 1800 (a [JUDGMENT CALL], configuration, not a ruled number). Compared against the INJECTED clock in UTC (FR-ADR-018). The 1800 must not appear as a literal in a constraint or a message — every customer-visible '30 minutes' is rendered from the variable.
    used_at                    timestamptz,  -- P-ACC-07 step 5 · P-ACC-08 step 4 · S-SCP-04 ('The password_reset_token.used_at column is explicitly excluded from the check and must still exist') - THE THIRD AND SEPARATE TIMESTAMP: it records the CUSTOMER SPENDING the token and has nothing to do with the send. The single-use guarantee is the conditional update `UPDATE password_reset_token SET used_at = :now WHERE id = :id AND used_at IS NULL` affecting exactly one row inside the password-change transaction — not a prior read. P-ACC-07 step 3 also sets it on every outstanding unused token for that user, so at most one live token exists per account. NOTE THE NEAR-MISS: S-SCP-04's excluded-column sweep bans `used_at` on `booking` and MUST NOT trip over this column.
    email_claimed_at           timestamptz,  -- P-ACC-07 step 5 and its column table ('a worker is holding this send job') · E4 P-TKT-12 step 2 and exceptions 3a, 4, 6 - A CLAIM, NOT A RECORD OF DELIVERY. Set by the conditional claim; CLEARED BACK TO NULL on an SES refusal or a SES_SEND_TIMEOUT_MS timeout (`UPDATE password_reset_token SET email_claimed_at = NULL WHERE id = :id AND email_sent_at IS NULL`); and overtaken by the age branch `email_claimed_at < now() - :stale_interval` (RECEIPT_CLAIM_STALE_SECONDS, 900) when a worker dies before it can clear anything. These are ONE reclaim mechanism with a fast path, not two.
    email_sent_at              timestamptz,  -- P-ACC-07 step 5 and its column table ('an email went out … never cleared by anything') · E4 P-TKT-12 step 4 and exception 3 - TERMINAL. Set only after SES accepts, and NEVER CLEARED BY ANYTHING — that is what makes a duplicate credential email impossible even if the queue delete fails and SQS redelivers a day later (S-TKT-15 asserts a redelivery 24 injected hours later makes 0 SES calls).
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- P-ACC-07 step 5 (the row holds `created_at`) · FR-ADR-018 · S-XCT-09 (every table carries created_at) - DEFAULT now() is FR-ADR-018's row-metadata fallback only; the application supplies created_at from the injected clock, because S-ACC-07 asserts `expires_at = created_at + 1800 seconds FROM THE INJECTED CLOCK`, which the database default alone cannot satisfy under an injected test clock.
    PRIMARY KEY (id),
    CONSTRAINT fk_password_reset_token__user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- The confirm endpoint's only lookup. DERIVED FROM THE NAMED QUERY — no document declares this index, and no document says whether it is unique (see gaps).
CREATE INDEX ix_password_reset_token__token_sha256 ON password_reset_token (token_sha256);
-- The per-user sweep that keeps at most one live token per account. DERIVED FROM THE NAMED QUERY, not declared by any document.
CREATE INDEX ix_password_reset_token__user_id ON password_reset_token (user_id);

-- --------------------------------------------------------------------------
-- screen - A hall. Six of them in v1, each belonging to the one cinema; it is the unit manager scope attaches to and the row every seat write takes SELECT ... FOR UPDATE on.
-- P-ADM-13 · P-ADM-16 · FR-ADR-010 · FR-ADR-011 · FR-ADR-022
CREATE TABLE screen (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- EP-ADM-17 path_params `screen_id: integer, positive`; EP-ADM-16 201 body `{id: integer, ...}` - Integer, as above. Referenced by showtime.screen_id, seat.screen_id and manager_screen_assignment (other clusters).
    cinema_id                  bigint NOT NULL,  -- P-ADM-25 · FR-ADR-010 · EP-ADM-16 request body `cinema_id: integer, must exist, required` · S-SCP-05 - NOT NULL and never defaulted server-side to the only cinema row — S-ADM-03 asserts POST /api/admin/screens with no cinema_id returns 422 precisely so a second venue costs an insert and not a migration. S-SCP-05 asserts the NOT NULL column and the FK to cinema(id) exist, positively: the test fails if the column is missing, so this column may NOT be optimised away even though the parent table holds one row.
    name                       text NOT NULL,  -- P-ADM-13 validation table; EP-ADM-16 / EP-ADM-17 request bodies; S-ADM-05 - 1..60 characters after trimming (0 -> 422, 60 -> 201, 61 -> 422), unique on (cinema_id, lower(trim(name))). Renaming stays permitted after showtimes exist — only seat identity freezes. The seed writes `SCREEN 1`..`SCREEN 6` (S-ADM-29 asserts the regex ^SCREEN [1-6]$ against seeded rows only; nothing in the running system enforces it).
    is_active                  boolean NOT NULL DEFAULT true,  -- P-ADM-16 · FR-ADR-012 · EP-ADM-16 201 body `is_active: true` · EP-ADM-15 - Withdrawal replaces deletion. A hall created through EP-ADM-16 starts in service; the PRD states the behaviour ('A hall starts empty and in service') but never says whether `true` is a database default or an application-set value — recorded here as a default because P-ADM-13's sibling rule for seat.is_active IS spelled 'default true'. A withdrawn hall keeps every showtime, seat and booking and still appears in reports (P-RPT-02 requires out-of-service halls in the dashboard's screens[]).
    version                    integer NOT NULL,  -- P-ADM-12 · FR-ADR-035 · S-ADM-14 (the version-column set is exactly movie, showtime, screen, seat_category, cinema) · S-ADM-05 · S-ADM-17 - Required on every PATCH of a screen, including the withdrawal toggle. Increments by exactly 1.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- S-XCT-09 - Same universal created_at criterion as cinema.
    PRIMARY KEY (id),
    CONSTRAINT fk_screen__cinema_id FOREIGN KEY (cinema_id) REFERENCES cinema (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- EXPRESSION index. Scoped to the cinema, not global — two venues may each have a `Hall 1`. A hall name differing only in case is the same name and is refused by the index rather than by a prior read.
CREATE UNIQUE INDEX uq_screen__name_ci ON screen (cinema_id, (lower(trim(name))));

-- --------------------------------------------------------------------------
-- manager_screen_assignment - One row per (manager user, screen) pair — the whole of manager scope; the router dependency resolves the caller's screen ids from it and every manager query filters on that set.
-- FR-ADR-011 (APPROVED) · P-ADM-17 · E8 S7.5 · S3.1 · P-XCT-05 preconditions
CREATE TABLE manager_screen_assignment (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- P-ADM-19 ('For `manager.screen_unassigned` it is the primary key the removed `manager_screen_assignment` row had') · S-ADM-18 (`SELECT count(*) FROM manager_screen_assignment WHERE id = :that_entity_id` returns 0) - A surrogate key is required because the audit row records the id the deleted row held. Generation mechanism not stated.
    user_id                    bigint NOT NULL,  -- FR-ADR-011 ('one row per (manager user, screen)') · S-ADM-18 (`(user_id, screen_id)` unique, asserted by name in information_schema) · P-ADM-19 (`before` carries exactly the keys user_id and screen_id) - Must reference an account whose role is `manager`: EP-ADM-24 returns 422 'That account is not a manager account. Screens can only be assigned to managers.' That check is application-side; no document asks for a database constraint on it.
    screen_id                  bigint NOT NULL,  -- FR-ADR-011 · EP-ADM-23/EP-ADM-24 (`screen_ids`: array of integer) · S-ADM-18 - OWNED JOINTLY WITH THE VENUE CLUSTER — the referenced table is `screen`.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- S-XCT-09 — no table in `public` other than `alembic_version` may lack a `created_at` · FR-ADR-018 - Required by the schema-wide rule rather than by a row that names this column. Flagged so the merge owner can see the derivation.
    PRIMARY KEY (id),
    CONSTRAINT uq_manager_screen_assignment__user_id_screen_id UNIQUE (user_id, screen_id),
    CONSTRAINT fk_manager_screen_assignment__user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_manager_screen_assignment__screen_id FOREIGN KEY (screen_id) REFERENCES screen (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- Resolved once per manager request by the router dependency. DERIVED FROM THE NAMED QUERY; the unique index above already leads on user_id, so this may be redundant — the merge owner should collapse it.
CREATE INDEX ix_manager_screen_assignment__user_id ON manager_screen_assignment (user_id);

-- --------------------------------------------------------------------------
-- movie_genre - The many-to-many join that gives a film its genres.
-- FR-ADR-021 ('genre is many-to-many through a join table'); P-ADM-01 happy path step 4; E1_browse.md P-BRW-04 ('at least one currently visible film has a movie_genre row pointing at it')
CREATE TABLE movie_genre (
    movie_id                   bigint NOT NULL,  -- P-ADM-01 step 4; FR-ADR-021 - Written in the SAME transaction as the movie insert.
    genre_id                   bigint NOT NULL,  -- P-ADM-01 (genre_ids: array of integer, 1..10, unique, each must exist); FR-ADR-021 - 1..10 rows per film; a duplicate genre_id in the request is 422. A film with zero rows here is legal on the wire (genres is []) even though the create endpoint refuses an empty array — S-BRW-02 asserts the empty case renders.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- E8 P-XCT-04 ('Every table carries `created_at`') · S-XCT-09 - Added by revision 0002 (a forward migration; 0001 is never edited). S-XCT-09 asserts information_schema returns zero public tables lacking created_at, except alembic_version and audit_log. DEFAULT now() at the database (FR-ADR-018): row metadata only, never read by a domain decision. Rows existing before 0002 carry the instant 0002 ran.
    PRIMARY KEY (movie_id, genre_id),
    CONSTRAINT fk_movie_genre__movie_id FOREIGN KEY (movie_id) REFERENCES movie (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_movie_genre__genre_id FOREIGN KEY (genre_id) REFERENCES genre (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

-- --------------------------------------------------------------------------
-- seat - One row per real, physical, individually sellable seat in a hall — created when the hall is configured, never per showtime; its id is half of the oversell guard's unique key.
-- P-ADM-13 · FR-ADR-016 · FR-ADR-022 · SRC-001 §5.2.1 · SRC-001 §5.2.3
CREATE TABLE seat (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- EP-ADM-20 path_params `seat_id: integer, positive`; EP-ADM-18/19 body `array of {id, row_label, seat_number, grid_row, grid_col, seat_category_id, is_active}`; E1 P-BRW-08 wire example `{"id": 4821, ...}` - Integer. This id is what showtime_seat.seat_id, booking_seat.seat_id and the Redis key `lock:seat:{showtime_id}:{seat_id}` all carry. FR-ADR-016 rejected a JSON-blob layout precisely because the oversell guard needs the seat to be a row with an id.
    screen_id                  bigint NOT NULL,  -- P-ADM-13 (identity is (screen_id, row_label, seat_number)) · FR-ADR-016 · S-ADM-06 (`SELECT count(*) FROM seat WHERE screen_id = :id`) · P-ADM-14 (`INSERT INTO showtime_seat (showtime_id, seat_id) SELECT :showtime_id, id FROM seat WHERE screen_id = :screen_id AND is_active = true`) - Seats belong to the screen, not to a showtime. Every seat write first takes SELECT ... FOR UPDATE on THIS screen row (P-ADM-13, P-ADM-14, P-ADM-15) — a build-session judgment call, stricter than any source, asserted by a pg_locks test in S-ADM-06.
    row_label                  text NOT NULL,  -- P-ADM-13 validation table · FR-ADR-016 · EP-ADM-19 / EP-ADM-20 request bodies · S-ADM-06 · S-ADM-07 - 1..4 characters, letters only. TWO formerly reserved questions sit on this column; SRC-004 R-4 (2026-10-18) RULES BOTH. (a) CASE - OPEN-SEATLABEL-01 RULED: row_label is stored as upper(trim(input)), enforced in the database by ck_seat__row_label_upper (row_label = upper(btrim(row_label))), so C12 and c12 cannot both exist - a lower-case or padded label is REFUSED by the CHECK, not silently rewritten; the application normalises before insert. Because every stored value is already upper-case and trimmed, the raw-column unique constraint below is now also the case-insensitive guard, and no expression index or citext is needed. (b) ALPHABET - OPEN-SEATALPHA-01 RULED: the letter I is PERMITTED (it matches wall signs). The seed's habit of skipping I is demonstration data and binds nothing, so NO CHECK bans any letter. (c) DEADLINE - P-ADM-14 freezes row_label the moment ANY showtime row exists on the screen; the ruling arrived before Phase 2, so no stored row predates it.
    seat_number                integer NOT NULL,  -- P-ADM-13 validation table · FR-ADR-016 · EP-ADM-19 - >= 1, an integer within the row. Decomposed from row_label deliberately: FR-ADR-016 rejected a single `A-12` label string because sorting A-2 after A-12 is the default a string produces and it is wrong, and because every render would become a parse. Frozen by P-ADM-14 alongside row_label.
    grid_row                   integer NOT NULL,  -- P-ADM-13 validation table · FR-ADR-016 · EP-ADM-19 · E1 P-BRW-08 (`gr` on the wire) - >= 1. Where the seat is DRAWN, deliberately separate from what it is CALLED — a hall with a mid-row gap has seat number 12 sitting at column 14. Not frozen: P-ADM-14 permits grid coordinate changes at any time, because a redrawn map changes nothing anyone bought.
    grid_col                   integer NOT NULL,  -- P-ADM-13 validation table · FR-ADR-016 · EP-ADM-19 · E1 P-BRW-08 (`gc` on the wire) - >= 1. Aisles, gaps and non-seat space are the ABSENCE of a seat at a coordinate — there is no placeholder, spacer or 'empty seat' row and no 'blocked' state.
    seat_category_id           bigint NOT NULL,  -- P-ADM-13 validation table ('must exist, non-null') · FR-ADR-016 · EP-ADM-19 · S-ADM-07 (frozen_fields) - NON-NULL foreign key to seat_category — a LOOKUP TABLE, never a PostgreSQL enum (see notes). This is what makes SRC-001 §5.2.3's 'distinguish seat categories, since we price them differently' true. Frozen by P-ADM-14 once a showtime exists, because a category change would reprice a live selling showtime.
    is_active                  boolean NOT NULL DEFAULT true,  -- P-ADM-13 validation table ('boolean | default true | ruled (FR-ADR-022)') · P-ADM-15 · FR-ADR-022 · E1 P-BRW-08 - In service / out of service. NOT a seat state and not a fifth value of the seat-map state enum — E1 P-BRW-08 argues this explicitly: a fifth enum value would make 'retired' and 'sold' mutually exclusive and a seat can be both. It is read by exactly one write path — P-ADM-14's `INSERT INTO showtime_seat ... WHERE screen_id = :screen_id AND is_active = true` — and it is emphatically NOT the occupancy denominator (E7:373-374 forbids computing it from seat.is_active). Toggling it to the value it already holds returns 409 LAYOUT_FROZEN, not a no-op 200, because a seat carries no version for a no-op to protect.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- S-XCT-09 - Same universal created_at criterion as cinema and screen.
    PRIMARY KEY (id),
    CONSTRAINT uq_seat__screen_id_row_label_seat_number UNIQUE (screen_id, row_label, seat_number),
    CONSTRAINT uq_seat__screen_id_grid_row_grid_col UNIQUE (screen_id, grid_row, grid_col),
    CONSTRAINT ck_seat__row_label_upper CHECK (row_label = upper(btrim(row_label))),
    CONSTRAINT fk_seat__screen_id FOREIGN KEY (screen_id) REFERENCES screen (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_seat__seat_category_id FOREIGN KEY (seat_category_id) REFERENCES seat_category (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

-- --------------------------------------------------------------------------
-- showtime - One screening of one film in one hall at one instant, created by hand by an admin, carrying its own base price and its frozen occupancy denominator.
-- P-ADM-07 (docs/03 PRD/sections/E6_admin.md S4); FR-ADR-018; FR-ADR-022; FR-ADR-037
CREATE TABLE showtime (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- FR-ADR-017 - Public and enumerable on purpose — FR-ADR-017: 'Knowing that showtime 41 exists discloses nothing; the seat map for it is already public to guests.' Scrapeability is handled by rate limiting, not authorisation.
    movie_id                   bigint NOT NULL,  -- P-ADM-07 validation table; EP-ADM-10 - The film NEED NOT BE PUBLISHED — a showtime may be scheduled against a draft (S-ADM-09 asserts 201 against a movie whose published_at is null). Editable on PATCH (EP-ADM-11 accepts movie_id).
    screen_id                  bigint NOT NULL,  -- P-ADM-07 validation table; P-ADM-09 - IMMUTABLE after creation. A PATCH carrying a different screen_id is 422 — 'Moving a showtime to another hall would move every existing booking onto seats that may not exist in the new hall.' Build-session judgment, Art III.9, stricter so unsigned. Screen must be is_active at create (409 LAYOUT_FROZEN otherwise).
    starts_at                  timestamptz NOT NULL,  -- P-ADM-07 validation table; FR-ADR-018; SRC-003 OPEN-LOCALE-01 - The advertised start, stored as a UTC INSTANT. Accepted and returned as a NAIVE LOCAL Asia/Kolkata string on the admin API; a value carrying Z, an offset or a zone name is 422 and is NEVER coerced. Serialised WITH the cinema's +05:30 offset on every customer surface. The zone is read from the cinema row, never from CINEMA_TIMEZONE at request time — S-ADM-04 asserts information_schema returns 0 columns matching '%timezone%' on showtime and screen, 'so a showtime reaches its zone only as showtime to screen to cinema.timezone'.
    ends_at                    timestamptz NOT NULL,  -- P-ADM-07 validation table; S-ACC-12 - STORED, never derived from movie.runtime_minutes. S-ACC-12 asserts SELECT is_nullable FROM information_schema.columns WHERE table_name='showtime' AND column_name='ends_at' returns NO. Strictly after starts_at in the MERGED row on a PATCH. Half-open interval [starts_at, ends_at) for the overlap predicate.
    base_price_paise           bigint NOT NULL,  -- P-ADM-10; P-PAY-03 exception 1; FR-ADR-037; SRC-003 OPEN-PRICE-01 - MONEY, INTEGER PAISE. P-PAY-03 exception 1: 'The column is bigint NOT NULL with no default, so the row cannot be created.' S-SEA-16 asserts schema.sql declares bigint for exactly showtime.base_price_paise, booking_seat.price_paise, booking_seat.base_price_paise_applied and booking.total_paise. That the price sits PER SHOWTIME rather than once globally is PROVISIONAL under SRC-003 OPEN-PRICE-01 / FR-ADR-037 — reversing it moves this column to a configuration value and backfills. Bound >= 1 at the admin write (P-ADM-10); P-PAY-03's pricing function separately states >= 0 — see notes.
    format_id                  bigint,  -- P-ADM-07 ('Format sits on the showtime, not on the film'); EP-ADM-10; EP-ADM-11 - OPTIONAL — 'one film runs 2D in one hall and 3D in another on the same day'. Null answers null on the browse surface and is EXCLUDED by any format filter. Must name an ACTIVE format row at write time; a showtime already carrying a withdrawn format keeps it. PATCH accepts null to clear it. This is the only place showtime.format_id is written.
    seat_count_at_creation     integer NOT NULL,  -- P-ADM-14 (E6_admin.md, 'A showtime's seat set is materialised when the showtime is created'); FR-ADR-022 - >= 1, equal to the number of showtime_seat rows written in the same transaction, NEVER RECOMPUTED — it is the occupancy denominator, and recomputing it would change last month's reported occupancy. S-ADM-08 asserts SELECT count(*) FROM showtime s WHERE s.seat_count_at_creation <> (SELECT count(*) FROM showtime_seat ss WHERE ss.showtime_id = s.id) returns 0. Creating a showtime on a screen with zero in-service seats is 409 LAYOUT_FROZEN, 'so no showtime can carry a zero denominator'.
    version                    integer NOT NULL,  -- P-ADM-09; FR-ADR-035; S-ADM-14 - Application-set to 1 on insert, +1 per successful write. Unchanged by a no-op. In S-ADM-14's exact five-table set.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- E8 P-XCT-04 ('Every table carries `created_at`') · S-XCT-09 - Added by revision 0002 (a forward migration; 0001 is never edited). S-XCT-09 asserts information_schema returns zero public tables lacking created_at, except alembic_version and audit_log. DEFAULT now() at the database (FR-ADR-018): row metadata only, never read by a domain decision. Rows existing before 0002 carry the instant 0002 ran.
    PRIMARY KEY (id),
    CONSTRAINT fk_showtime__movie_id FOREIGN KEY (movie_id) REFERENCES movie (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_showtime__screen_id FOREIGN KEY (screen_id) REFERENCES screen (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_showtime__format_id FOREIGN KEY (format_id) REFERENCES format (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- Verbatim: 'SELECT indexdef FROM pg_indexes contains an index on each of showtime(starts_at), showtime(screen_id, starts_at) ...' — the dashboard computes every figure live from stored rows with no rollup and no materialised view.
CREATE INDEX ix_showtime__starts_at ON showtime (starts_at);
-- Same criterion. Also serves the admin day list (EP-ADM-09: screen_id + local date) and the P-ADM-08 overlap predicate run inside the screen row lock.
CREATE INDEX ix_showtime__screen_id_starts_at ON showtime (screen_id, starts_at);

-- --------------------------------------------------------------------------
-- booking - One confirmed purchase: one user, one showtime, one captured payment, one unique customer-facing reference, and a stored total.
-- E3 P-PAY-01 · E3 P-PAY-10 step 7 · FR-ADR-014 · FR-ADR-039
CREATE TABLE booking (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- FR-ADR-020 (idempotency_record.id is 'bigint identity') · E6 P-ADM-19 audit_log id table ('bigint identity') · S-XCT-08 ('booking_id 9008') - NOT uuid. No document in this project uses a uuid primary key anywhere; the two places a PK type is spelled out both read 'bigint identity', and every id in every criterion and every endpoint body is a small integer (booking_id 9008, user_id 4471, showtime_id 7/41/77, seat_id 312/402). EP-PAY-01's 201 body declares booking_id as 'integer'. The brief's uuid default is overridden here by the sources, as the brief permits.
    reference                  text NOT NULL,  -- E4 P-TKT-01 · FR-ADR-015 · S-TKT-01 - THE COLUMN IS NAMED `reference`, not reference_code and not booking_reference. Uppercase, with NO `FR-` prefix and NO hyphens stored (those are presentation only). OPEN-REFCHAR-01 is RULED by SRC-004 R-5 (2026-10-18): the alphabet is SRC-003 OPEN-TICKET-01's set (P-TKT-01's 23456789ABCDEFGHJKMNPQRSTVWXYZ) MINUS Z S B G, i.e. 23456789ACDEFHJKMNPQRTVWXY (26 characters), and every reference carries ONE TRAILING CHECK CHARACTER from the same alphabet; the length stays 8 (7 random characters + the check character, SRC-004 R-5 [JUDGMENT CALL]), so the stored form is 8 characters and the display form FR-XXXX-XXXX is unchanged. ck_booking__reference_charset enforces the alphabet and the length in the database; it cannot verify the check character's ARITHMETIC, which SRC-004 R-5 leaves to the build session as a [JUDGMENT CALL] recorded in the code that implements it. P-TKT-01 and the Bible state the same 26-character alphabet and 8-character length. The UNIQUE constraint, not the alphabet, remains the collision guard (P-TKT-01).
    user_id                    bigint NOT NULL,  -- S-ACC-10 (verbatim: 'booking.user_id integer NOT NULL REFERENCES users(id) ON DELETE RESTRICT') · FR-ADR-014 · E4 EP-TKT-01 authorisation_rule - Type spelled `integer` (not bigint) by S-ACC-10. It must match users(id); see notes[] — the merge owner must reconcile this with booking.id being bigint. The owner is always taken from the JWT, never from the request body (S-ACC-10 route-table walk).
    showtime_id                bigint NOT NULL,  -- E7 P-RPT-03 formula ('JOIN booking b ON b.showtime_id = st.id') · S-PAY-06 · S-PAY-15 · EP-PAY-01 201 body - Integer, matching E6 P-ADM-14's showtime_seat.showtime_id 'integer'.
    payment_id                 bigint NOT NULL,  -- E3 P-PAY-07 ('booking.payment_id points at payment.id, not the reverse') · E3 P-PAY-01 ('no state in which a booking exists without a captured payment') · S-PAY-05 · S-SCP-12 · E7 P-RPT-12 - THE DIRECTION IS LOAD-BEARING AND SETTLED IN FIVE PLACES. payment carries NO booking_id column: the payment row is inserted at P-PAY-10 step 6 and the booking at step 7, so a payment.booking_id could not be satisfied at insert time. NOT NULL is what makes 'no booking without a payment record' a database fact rather than a test; see gaps[] for the half that is not expressible (the payment being in a terminal captured state).
    total_paise                bigint NOT NULL,  -- E3 P-PAY-04 · FR-ADR-039 · S-PAY-01 · S-SEA-16 - Integer minor unit. The sum of the ALREADY-ROUNDED per-seat prices; the total is never itself rounded. Deliberately denormalised (FR-ADR-039) — the equality total_paise = SUM(booking_seat.price_paise) is asserted at write time as a TEST, explicitly NOT as a database constraint, because a constraint would need a trigger. The minor-unit ratio 100 is CURRENCY_MINOR_UNIT_RATIO, a named configuration value, and appears in no column name, comment or constraint.
    status                     text NOT NULL,  -- FR-ADR-013 · E3 P-PAY-12 · E7 P-RPT-03 ("b.status = 'confirmed'") · S-PAY-11 · S-SCP-14 - EXCLUDED IS NOT BLOCKED (SRC-001 §6.6). Written exactly once, by the confirm insert, to 'confirmed'. No v1 endpoint reads or writes it; it appears in no v1 request or response schema. `SELECT DISTINCT status FROM booking` must return exactly one row after the whole suite. TYPE IS UNSOURCED — no document says whether this is a Postgres enum or text, and no document names any value other than 'confirmed'. Declaring an enum here would mean naming a 'cancelled' value, which is the reserved question OPEN-CANCEL-01/OPEN-SHOWCANCEL-01. Reported as a gap rather than decided.
    cancelled_at               timestamptz,  -- FR-ADR-013 · E3 P-PAY-12 · E4 P-TKT-09 · S-PAY-11 · S-SCP-14 - EXCLUDED IS NOT BLOCKED (SRC-001 §6.6). Stays null for every row v1 ever creates: `SELECT count(*) FROM booking WHERE cancelled_at IS NOT NULL` returns 0. Exists because adding a column to a table already holding real bookings is a migration on live data with a backfill nobody can verify. S-SCP-04 explicitly permits it while banning refund/tax/fee/discount/points/used_at names on this table.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- E8 P-XCT-04 preconditions ('Every table carries created_at') · S-XCT-08 ('SELECT b.id, b.user_id, b.created_at ...') · S-XCT-09 · E5 P-ACC-11 ordering tie-breaker - UTC instant. Serialised to customers with the CINEMA ROW's UTC offset (never Z, never a hardcoded zone) — EP-PAY-01 returns it as created_at, EP-ACC-07 as booked_at. It is also an ordering tie-breaker for the bookings list (S-ACC-12: upcoming ordered by showtime.starts_at asc, booking.created_at desc, booking.id asc).
    PRIMARY KEY (id),
    CONSTRAINT uq_booking__reference UNIQUE (reference),
    CONSTRAINT ck_booking__reference_charset CHECK (reference ~ '^[23456789ACDEFHJKMNPQRTVWXY]{8}$'),
    CONSTRAINT fk_booking__user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_booking__showtime_id FOREIGN KEY (showtime_id) REFERENCES showtime (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_booking__payment_id FOREIGN KEY (payment_id) REFERENCES payment (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- The dashboard aggregate drives from showtime, filtered by period and screen, then joins booking on showtime_id. Named as a required index by the PRD and asserted by S-RPT-16 against pg_indexes.
CREATE INDEX ix_booking__showtime_id ON booking (showtime_id);
-- The takings query joins payment on p.id = b.payment_id.
CREATE INDEX ix_booking__payment_id ON booking (payment_id);

-- --------------------------------------------------------------------------
-- showtime_seat - The showtime's MATERIALISED SEAT SET: one row per seat that was in service on that screen at the instant the showtime was created. Written once, by showtime creation, and edited by nothing, ever.
-- P-ADM-14 (docs/03 PRD/sections/E6_admin.md, heading 'A showtime's seat set is materialised when the showtime is created — this row owns that rule'); FR-ADR-022
CREATE TABLE showtime_seat (
    showtime_id                bigint NOT NULL,  -- P-ADM-14 server-side validation table ('must exist; written only by showtime creation ... never client-supplied')
    seat_id                    bigint NOT NULL,  -- P-ADM-14 server-side validation table ('must be a seat of the showtime's screen and in service at the creation instant ... never client-supplied')
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- E8 P-XCT-04 ('Every table carries `created_at`') · S-XCT-09 - Added by revision 0002 (a forward migration; 0001 is never edited). S-XCT-09 asserts information_schema returns zero public tables lacking created_at, except alembic_version and audit_log. DEFAULT now() at the database (FR-ADR-018): row metadata only, never read by a domain decision. Rows existing before 0002 carry the instant 0002 ran.
    PRIMARY KEY (showtime_id, seat_id),
    CONSTRAINT uq_showtime_seat__showtime_id_seat_id UNIQUE (showtime_id, seat_id),
    CONSTRAINT fk_showtime_seat__showtime_id FOREIGN KEY (showtime_id) REFERENCES showtime (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_showtime_seat__seat_id FOREIGN KEY (seat_id) REFERENCES seat (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

-- --------------------------------------------------------------------------
-- booking_seat - One row per booked seat: the seat-occupancy record that carries the oversell guard and the immutable per-seat price snapshot.
-- FR-ADR-024 ('The unique constraint is declared on the seat-occupancy table — one row per (booking, seat)') · FR-ADR-039 · E3 P-PAY-05
CREATE TABLE booking_seat (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- project id convention: FR-ADR-020, E6 P-ADM-19 ('bigint identity') - NO DOCUMENT NAMES A PRIMARY KEY FOR THIS TABLE. See gaps[] — the merge owner must choose between a surrogate id and a composite PK on (booking_id, seat_id). Nothing in any criterion selects a booking_seat id.
    booking_id                 bigint NOT NULL,  -- E3 P-PAY-10 step 7 · S-PAY-03 · S-PAY-07 · S-SCP-13 · S-XCT-08 · E7 P-RPT-03 formula - Every criterion in the Bible that reads a booked seat filters on booking_id.
    showtime_id                bigint NOT NULL,  -- FR-ADR-024 · E3 P-PAY-11 · S-XCT-01 · S-XCT-02 · S-XCT-03 · S-PAY-09 · S-SEA-13 · S-SEA-16 · S-SEA-18 · S-SEA-20 - DENORMALISED FROM booking.showtime_id ON PURPOSE. It exists so the oversell unique constraint can be (showtime_id, seat_id) — the guarantee has to be at seat granularity across the whole showtime, not per booking. At least nine acceptance criteria run `SELECT count(*) FROM booking_seat WHERE showtime_id=? AND seat_id=?` directly. Nothing in the documents states how showtime_id is kept consistent with booking.showtime_id.
    seat_id                    bigint NOT NULL,  -- FR-ADR-024 · S-PAY-09 ('seat_id is an integer foreign key and seat_label carries the human form such as F7; a query comparing seat_id to a label string raises invalid input syntax for type integer against a correct schema') · S-XCT-08 · S-XCT-34 - INTEGER, NOT A LABEL. The human-readable form (F7, C12) lives on the `seat` table and is joined for display (S-XCT-08: `JOIN seat s ON s.id = bs.seat_id`); it is never copied onto booking_seat.
    price_paise                bigint NOT NULL,  -- FR-ADR-039 · E3 P-PAY-05 · S-PAY-01 · S-SEA-16 · E7 P-RPT-03 - The rounded per-seat price the customer actually paid, snapshotted at HOLD acquisition (not at confirm) and copied onto this row; never recomputed by any display path, receipt, bookings list or dashboard. Integer minor unit, bigint.
    base_price_paise_applied   bigint NOT NULL,  -- FR-ADR-039 · E3 P-PAY-05 (column table) · S-PAY-03 · S-SEA-16 - The showtime base price that produced price_paise. Stored so the figure is auditable — SRC-001 §7.6 requires the system to answer for its own records; storing only price_paise makes it impossible to tell a 33.33% uplift on Rs 275.00 from a 20% uplift on something else. Money column: bigint, name ends _paise.
    uplift_basis_points_applied bigint NOT NULL,  -- FR-ADR-039 · E3 P-PAY-05 (column table) · S-PAY-03 · S-SEA-16 - The seat category's uplift in basis points at the time of booking. NOT a money column — its name deliberately does not end in _paise, and S-PAY-01's assertion (money columns on booking/booking_seat/payment ending in _paise are EXACTLY total_paise, price_paise, base_price_paise_applied, amount_paise) depends on that. bigint, NOT integer: it snapshots seat_category.uplift_basis_points, which is bigint because S-ADM-13 requires 368934881464190 to be ACCEPTED; an integer snapshot would make the first booking of a seat in that category fail with 'integer out of range' (RUN_LOG F-4).
    seat_category_id           bigint NOT NULL,  -- FR-ADR-039 ('the category at the time of booking, copied, not joined for display') · E3 P-PAY-05 ('integer, positive, non-null') · S-PAY-03 - Copied rather than joined, so a later category rename or re-categorisation cannot rewrite what a past receipt says.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- E8 P-XCT-04 ('Every table carries created_at') · S-XCT-09 - S-XCT-09 asserts information_schema returns zero public tables lacking created_at.
    PRIMARY KEY (id),
    CONSTRAINT uq_booking_seat__showtime_id_seat_id UNIQUE (showtime_id, seat_id),
    CONSTRAINT fk_booking_seat__booking_id FOREIGN KEY (booking_id) REFERENCES booking (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_booking_seat__seat_id FOREIGN KEY (seat_id) REFERENCES seat (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_booking_seat__showtime_id FOREIGN KEY (showtime_id) REFERENCES showtime (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_booking_seat__seat_category_id FOREIGN KEY (seat_category_id) REFERENCES seat_category (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
-- Every read of a booking's seats — the receipt, the bookings list, the confirmation page, the takings sum — joins booking_seat on booking_id.
CREATE INDEX ix_booking_seat__booking_id ON booking_seat (booking_id);

-- --------------------------------------------------------------------------
-- idempotency_record - The per-user idempotency guard for booking confirmation: inserted first, inside the booking transaction, so two simultaneous retries collide in the database rather than both booking.
-- FR-ADR-020 · E3 P-PAY-09 · SRC-002 §8.3.1 · SRC-001 §5.3.2
CREATE TABLE idempotency_record (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- FR-ADR-020 column table (verbatim: 'id | bigint identity') - The one place in this cluster where a primary key type is spelled out in a source document.
    user_id                    bigint NOT NULL,  -- FR-ADR-020 ('non-null foreign key. The key is scoped per user') · E3 P-PAY-09 ('Scope is per user') - SCOPE IS PER USER, NOT GLOBAL. P-PAY-09: 'Two customers can generate the same key — a weak client generator, or a copied request — and a global scope would hand one of them the other's booking.' S-PAY-06 asserts the same key from a different user id inserts cleanly and confirms normally. Type follows booking.user_id / users(id).
    idempotency_key            text NOT NULL,  -- FR-ADR-020 ('the client''s header value, text') · E3 P-PAY-09 · EP-PAY-01 headers · S-PAY-06 - 1..255 characters, REQUIRED — a missing header is 400 REQUEST_INVALID, never a permitted omission. Compared as an EXACT BYTE SEQUENCE: never trimmed, lowercased, casefolded or unicode-normalised. S-PAY-06 proves it by inserting a key, the same key with one trailing space, and the same key uppercased, and asserting three rows. The value is minted by the CLIENT (crypto.randomUUID(), 36 chars, 122 random bits), once per confirm attempt, never by the server.
    request_fingerprint        text NOT NULL,  -- FR-ADR-020 ('a hash of the canonicalised request body') · E3 P-PAY-09 - For EP-PAY-01 the canonicalised body is hold_token + showtime_id. A same-key request whose fingerprint differs is 422 IDEMPOTENCY_KEY_REUSED, permanently, because the record is never deleted.
    status                     text NOT NULL,  -- FR-ADR-020 ('status | in_progress or completed') · E3 P-PAY-09 - TYPE NAME IS UNSOURCED. The two values are a closed, fully documented set, but no document says whether the SQL type is a Postgres enum or text — the merge chose text. Closed vocabulary, enforced by a CHECK rather than a PostgreSQL enum type
    booking_id                 bigint,  -- FR-ADR-020 ('nullable foreign key, set when the booking commits') · E3 P-PAY-09 happy path step 4 · E3 P-PAY-10 step 11 - Null while in_progress; written at step 11 together with response_body and status='completed'.
    response_body              jsonb,  -- FR-ADR-020 ('jsonb, the response that was returned') · E3 P-PAY-09 · S-PAY-06 - Returned BYTE FOR BYTE to a duplicate whose winner is completed — never a second booking and never a second capture. Null while in_progress.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- FR-ADR-020 ('created_at, completed_at | timestamptz') · E8 P-XCT-04 · S-XCT-09
    completed_at               timestamptz,  -- FR-ADR-020 ('created_at, completed_at | timestamptz') · E3 P-PAY-09 - Null while in_progress.
    PRIMARY KEY (id),
    CONSTRAINT uq_idempotency_record__user_id_idempotency_key UNIQUE (user_id, idempotency_key),
    CONSTRAINT ck_idempotency_record__status CHECK (status IN ('in_progress', 'completed')),
    CONSTRAINT fk_idempotency_record__user_id FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_idempotency_record__booking_id FOREIGN KEY (booking_id) REFERENCES booking (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

-- --------------------------------------------------------------------------
-- receipt_dispatch - One durable claim-and-outcome row per booking recording whether the receipt email was claimed, sent, failed or suppressed — the guard that makes two senders for one booking impossible, and the only record of what SES was asked to do.
-- FR-ADR-032 Decision; E4 P-TKT-05 'Send exactly one receipt per booking, and retry the ones that fail' Preconditions
CREATE TABLE receipt_dispatch (
    id                         bigint GENERATED ALWAYS AS IDENTITY NOT NULL,  -- E4 P-TKT-05 happy path step 2 (the claim UPDATE ends `RETURNING id`) - THE TYPE IS NOT STATED. Same evidence and same caveat as outbox_message.id — see gaps. The claim returns it; nothing else in any document reads or joins on it.
    booking_id                 bigint NOT NULL,  -- FR-ADR-032 Decision ('A `receipt_dispatch` claim row, unique on `booking_id`'); E4 P-TKT-05 Preconditions; Bible S-PAY-07 - TYPE IS FORCED BY A CRITERION'S SQL: S-PAY-07 runs `... WHERE r.booking_id = (o.payload->>'booking_id')::bigint`, so this column and booking.id must both be bigint or that test cannot run. This is the one hard type fact in this cluster.
    status                     text NOT NULL,  -- E4 P-TKT-05 Preconditions ('`status` (`pending` / `sending` / `sent` / `failed` / `suppressed`)'); E4 P-TKT-04 'The `suppressed` state' block; E4 P-TKT-10 state table - FIVE values. Created `pending` by the booking transaction; `suppressed` is written ONLY by the seed script and by nothing in the running application, has no incoming edge from any other state and no outgoing edge at all (P-TKT-05 state machine). `sent` means SES ACCEPTED the message for delivery and is never revised — P-TKT-11: 'evidence of dispatch, never of receipt'. Modelled as text + CHECK; no document mandates a native enum.
    dispatch_seq               integer NOT NULL,  -- E4 P-TKT-05 Preconditions ('`dispatch_seq` (integer, `>= 1`)'); E4 P-TKT-04 happy path step 1 and Server-side validation; E4 P-TKT-07 happy path step 5; S8 merge report row X-10 - BUILD-SESSION EXTENSION, EXPLICITLY FLAGGED FOR 06 DataModel TO CONFIRM. It is the reconciliation of FR-ADR-032 (a `sent` claim is not retryable) against FR-ADR-048 (a resend control that re-enqueues the job): one row per booking stays unique on booking_id, and the worker's claim is conditional on the sequence so a stale redelivery cannot re-send. E4 lane notes: 'The merge pass and `06 DataModel` must confirm both, and if either is rejected the resend control needs a different mechanism.' Written 1 in the booking transaction; incremented only by an accepted resend.
    claimed_at                 timestamptz,  -- E4 P-TKT-05 Preconditions and happy path step 2 (`claimed_at=now()` in the claim UPDATE, and `claimed_at < now() - :stale_interval` in its WHERE) - THE WORKER'S CLAIM COLUMN. Null on a row the booking transaction just created ('every timestamp null', P-TKT-04 step 1). IT IS NOT CLEARED ON FAILURE — unlike password_reset_token.email_claimed_at, which P-TKT-12 exception 4 clears to NULL explicitly. A failed receipt send moves status to 'failed' and leaves claimed_at set; the 'failed' branch of the claim's WHERE clause is what makes it retryable. Bible S-TKT-07 requires claimed_at to be written from the INJECTED clock and the staleness threshold bound from the same clock, asserting `rg -n 'now\(\)|CURRENT_TIMESTAMP' backend/app/workers` returns 0 hits — see notes, this contradicts the literal `now()` in the PRD's published claim statement.
    sent_at                    timestamptz,  -- E4 P-TKT-05 happy path step 5 ('`sent_at=now()`'); E4 P-TKT-04 'The `suppressed` state' block - Set only when SES accepted. Never cleared. Bible S-TKT-08 asserts it reads null on a timed-out send.
    ses_message_id             text,  -- E4 P-TKT-05 Preconditions and happy path step 5 ('`ses_message_id=<the id SES returned>`'); FR-ADR-032 Consequences; FR-ADR-060 - The id SES returned on acceptance. FR-ADR-060: it 'is what makes "did this send" answerable'. Null on failure, on timeout and on a suppressed row.
    attempts                   integer NOT NULL,  -- E4 P-TKT-05 Preconditions and happy path step 2 ('`attempts=attempts+1`'); E4 P-TKT-04 happy path step 1 ('`attempts = 0`') - Written 0 in the booking transaction; no DB default stated. LOAD-BEARING BEYOND COUNTING: P-TKT-07 steps 3 and 4 use attempts=0 versus attempts>0 to distinguish 'the first receipt has not been attempted yet' (202 queued:false, no token spent) from 'a resend is already in flight' (202 queued:false). It is 0 only on a row no worker has ever claimed.
    last_error                 text,  -- E4 P-TKT-05 Preconditions, exception rows 2 and 2a; FR-ADR-049 dimension 5 - Carries the SES error. MUST DISTINGUISH A TIMEOUT FROM A REFUSAL: P-TKT-05 exception 2a — 'last_error records that the call timed out rather than that SES refused, so the two are distinguishable afterwards by the operator'. Bible S-TKT-08 tests exactly that: last_error contains 'timeout' and does not contain the SES refusal string, and an SES error is 'distinguishable from the timeout case by that string'.
    created_at                 timestamptz NOT NULL DEFAULT now(),  -- E8 P-XCT-04 ('Every table carries `created_at`') · S-XCT-09 - Added by revision 0002 (a forward migration; 0001 is never edited). S-XCT-09 asserts information_schema returns zero public tables lacking created_at, except alembic_version and audit_log. DEFAULT now() at the database (FR-ADR-018): row metadata only, never read by a domain decision. Rows existing before 0002 carry the instant 0002 ran.
    PRIMARY KEY (id),
    CONSTRAINT uq_receipt_dispatch__booking_id UNIQUE (booking_id),
    CONSTRAINT ck_receipt_dispatch__1 CHECK (status IN ('pending', 'sending', 'sent', 'failed', 'suppressed')),
    CONSTRAINT ck_receipt_dispatch__2 CHECK (dispatch_seq >= 1),
    CONSTRAINT fk_receipt_dispatch__booking_id FOREIGN KEY (booking_id) REFERENCES booking (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);

-- --------------------------------------------------------------------------
-- Roles.  The application never connects as the owner of these
-- tables.  Building against the restricted role from the first line
-- is the only way a missing grant is found here rather than in AWS,
-- where the superuser this schema was written under does not exist.
-- ORDER: the roles must EXIST before this file runs.  schema.sql creates
-- no role: roles belong to the operator - checks/roles_local.sql locally,
-- the client on RDS.  Run as the owner, a missing role makes the GRANT
-- below fail and the whole file roll back, which is the correct failure.
-- frontrow_owner: owns every table and runs migrations. NEVER the role the application connects as.
-- SRC-002 (build against a restricted role) - the role NAMES are a [JUDGMENT CALL]: no document in the repository contains a single CREATE ROLE, GRANT or REVOKE. · CREATED BY THE OPERATOR, NOT BY schema.sql: checks/roles_local.sql locally, the client on RDS (AWS_PREP_QUEUE row 20); schema.sql only GRANTs and fails loudly if the role is absent.

-- frontrow_app: the application role. Not a superuser and not the owner. The two-role split is FORCED, not stylistic: S-XCT-07 asserts that table_privileges for audit_log and current_user returns EXACTLY two rows. Observed on PostgreSQL 16.14 - a table's OWNER sees seven (DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE), so a single-role design cannot satisfy that criterion at all. With a separate owner the same query returns exactly INSERT and SELECT.
-- S-XCT-07; FR-ADR-019 (audit is append-only at the role level, not by convention); E8 S7.11 · least-privilege matrix: checks/roles_local.sql section 3 (each table's privileges cited there; verify_invariants.sql A4 fails on any excess) · CREATED BY THE OPERATOR, NOT BY schema.sql: checks/roles_local.sql locally, the client on RDS (AWS_PREP_QUEUE row 20); schema.sql only GRANTs and fails loudly if the role is absent.
GRANT USAGE ON SCHEMA public TO frontrow_app;
GRANT SELECT, INSERT, DELETE ON admin_grant TO frontrow_app;
GRANT SELECT, INSERT ON audit_log TO frontrow_app;
GRANT SELECT, INSERT ON booking TO frontrow_app;
GRANT SELECT, INSERT ON booking_seat TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON certification TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON cinema TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON format TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON genre TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON idempotency_record TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON language TO frontrow_app;
GRANT SELECT, INSERT, DELETE ON manager_screen_assignment TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON movie TO frontrow_app;
GRANT SELECT, INSERT, DELETE ON movie_genre TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON outbox_message TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON password_reset_token TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON payment TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON receipt_dispatch TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON screen TO frontrow_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON seat TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON seat_category TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON showtime TO frontrow_app;
GRANT SELECT, INSERT ON showtime_seat TO frontrow_app;
GRANT SELECT, INSERT, UPDATE ON users TO frontrow_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO frontrow_app;

COMMIT;
